SELECT * FROM sync_metadata
WHERE tenant_id = #{tenantId}
  AND entity_kind = #{entityKind}
  AND source_service = #{sourceService}
  AND scope_key_hash = #{scopeKeyHash}
  AND business_key_hash = #{businessKeyHash}
  AND delete_flag = 0
LIMIT 1

SELECT * FROM sync_metadata
WHERE tenant_id = #{tenantId}
  AND entity_kind = #{entityKind}
  AND source_service = #{sourceService}
  AND scope_key_hash = #{scopeKeyHash}
  AND delete_flag = 0
ORDER BY id

mapper.update:
UPDATE sync_metadata
SET delete_flag = id,
    deleted_at = #{deletedAt},
    updated_at = now()
WHERE tenant_id = #{tenantId}
  AND entity_kind = #{entityKind}
  AND source_service = #{sourceService}
  AND scope_key_hash = #{scopeKeyHash}
  AND business_key_hash = #{businessKeyHash}
  AND delete_flag = 0

UPDATE sync_metadata
SET target_status = #{targetStatus},
    updated_at = now()
WHERE tenant_id = #{tenantId}
  AND entity_kind = #{entityKind}
  AND source_service = #{sourceService}
  AND scope_key_hash = #{scopeKeyHash}
  AND business_key_hash = #{businessKeyHash}
  AND delete_flag = 0

UPDATE sync_metadata
SET target_id = #{targetId},
    updated_at = now()
WHERE tenant_id = #{tenantId}
  AND entity_kind = #{entityKind}
  AND source_service = #{sourceService}
  AND scope_key_hash = #{scopeKeyHash}
  AND business_key_hash = #{businessKeyHash}
  AND delete_flag = 0
  AND target_id IS DISTINCT FROM #{targetId}
